-- Create "facilities" table
CREATE TABLE "facilities" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "name" text NOT NULL, "time_zone" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"), CONSTRAINT "facilities_name_valid" CHECK ((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200)), CONSTRAINT "facilities_time_zone_valid" CHECK ((length(btrim(time_zone)) >= 1) AND (length(btrim(time_zone)) <= 64)));
-- Create "users" table
CREATE TABLE "users" ("id" uuid NOT NULL DEFAULT gen_random_uuid(), "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("id"));
-- Create "facility_memberships" table
CREATE TABLE "facility_memberships" ("facility_id" uuid NOT NULL, "user_id" uuid NOT NULL, "role" text NOT NULL, "status" text NOT NULL DEFAULT 'active', "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("facility_id", "user_id"), CONSTRAINT "facility_memberships_facility_fk" FOREIGN KEY ("facility_id") REFERENCES "facilities" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "facility_memberships_user_fk" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "facility_memberships_role_valid" CHECK (role = ANY (ARRAY['owner'::text, 'manager'::text, 'staff'::text])), CONSTRAINT "facility_memberships_status_valid" CHECK (status = ANY (ARRAY['active'::text, 'revoked'::text])));
-- Create index "facility_memberships_user_idx" to table: "facility_memberships"
CREATE INDEX "facility_memberships_user_idx" ON "facility_memberships" ("user_id");
-- Create "products" table
CREATE TABLE "products" ("facility_id" uuid NOT NULL, "id" uuid NOT NULL DEFAULT gen_random_uuid(), "kind" text NOT NULL, "name" text NOT NULL, "published" boolean NOT NULL DEFAULT false, "currency" text NOT NULL, "unit_price_minor" bigint NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("facility_id", "id"), CONSTRAINT "products_facility_fk" FOREIGN KEY ("facility_id") REFERENCES "facilities" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "products_currency_valid" CHECK (currency ~ '^[A-Z]{3}$'::text), CONSTRAINT "products_kind_valid" CHECK (kind = ANY (ARRAY['private_sauna'::text, 'shared_sauna'::text, 'day_tent'::text, 'overnight_tent'::text])), CONSTRAINT "products_name_valid" CHECK ((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 200)), CONSTRAINT "products_price_valid" CHECK (unit_price_minor >= 0));
-- Create "reservations" table
CREATE TABLE "reservations" ("facility_id" uuid NOT NULL, "id" uuid NOT NULL DEFAULT gen_random_uuid(), "user_id" uuid NOT NULL, "status" text NOT NULL DEFAULT 'draft', "currency" text NOT NULL, "total_minor" bigint NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("facility_id", "id"), CONSTRAINT "reservations_facility_fk" FOREIGN KEY ("facility_id") REFERENCES "facilities" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "reservations_user_fk" FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "reservations_currency_valid" CHECK (currency ~ '^[A-Z]{3}$'::text), CONSTRAINT "reservations_status_valid" CHECK (status = ANY (ARRAY['draft'::text, 'pending_payment'::text, 'confirmed'::text, 'cancelled'::text, 'expired'::text])), CONSTRAINT "reservations_total_valid" CHECK (total_minor >= 0));
-- Create index "reservations_user_idx" to table: "reservations"
CREATE INDEX "reservations_user_idx" ON "reservations" ("user_id", "facility_id");
-- Create "reservation_items" table
CREATE TABLE "reservation_items" ("facility_id" uuid NOT NULL, "id" uuid NOT NULL DEFAULT gen_random_uuid(), "reservation_id" uuid NOT NULL, "product_id" uuid NOT NULL, "product_name_snapshot" text NOT NULL, "quantity" integer NOT NULL, "unit_price_minor" bigint NOT NULL, "starts_at" timestamptz NOT NULL, "ends_at" timestamptz NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), PRIMARY KEY ("facility_id", "id"), CONSTRAINT "reservation_items_product_fk" FOREIGN KEY ("facility_id", "product_id") REFERENCES "products" ("facility_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "reservation_items_reservation_fk" FOREIGN KEY ("facility_id", "reservation_id") REFERENCES "reservations" ("facility_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "reservation_items_name_valid" CHECK ((length(btrim(product_name_snapshot)) >= 1) AND (length(btrim(product_name_snapshot)) <= 200)), CONSTRAINT "reservation_items_price_valid" CHECK (unit_price_minor >= 0), CONSTRAINT "reservation_items_quantity_valid" CHECK (quantity > 0), CONSTRAINT "reservation_items_time_valid" CHECK (isfinite(starts_at) AND isfinite(ends_at) AND (starts_at < ends_at)));
-- Create index "reservation_items_product_idx" to table: "reservation_items"
CREATE INDEX "reservation_items_product_idx" ON "reservation_items" ("facility_id", "product_id");
-- Create index "reservation_items_reservation_idx" to table: "reservation_items"
CREATE INDEX "reservation_items_reservation_idx" ON "reservation_items" ("facility_id", "reservation_id");
